	"google.golang.org/grpc/credentials/insecure"
)

// ComposeStack manages a docker-compose stack for testing.
type ComposeStack struct {
	composeFiles []string
	projectName  string
	t            *testing.T
	log          *TestLogger
	ctx          context.Context
	composeCmd   []string  // pinned Compose executable from Bazel runfiles
	composeEnv   []string  // environment shared by compose commands
	logCmd       *exec.Cmd // background "docker compose logs -f" process
}

// fileArgs returns the "-f <path>" pairs naming this stack's compose files, in
// the order compose must merge them.
func (s *ComposeStack) fileArgs() []string {
	args := make([]string, 0, len(s.composeFiles)*2)
	for _, f := range s.composeFiles {
		args = append(args, "-f", f)
	}
	return args
}

// command builds a compose invocation for this stack, with the compose files
// and project name already applied.
func (s *ComposeStack) command(args ...string) []string {
	full := append([]string{}, s.composeCmd[1:]...)
	full = append(full, s.fileArgs()...)
	full = append(full, "-p", s.projectName)
	return append(full, args...)
}

// ComposeOption customizes how a ComposeStack is created.
type ComposeOption func(*composeOptions)

type composeOptions struct {
	// buildContextFiles maps a path inside the synthesized docker build
	// context to the workspace-relative runfile it is staged from.
	buildContextFiles map[string]string
	// overlays are additional compose files merged over the base one, in order.
	overlays []string
}

// WithBuildContext stages the given files into a synthesized docker build
// context directory and points the compose build context variable (REPO_ROOT)
// at it. Keys are context-relative destination paths that must match the
// Dockerfile COPY sources and the compose `dockerfile:` path (e.g.
// ".docker-bin/gateway", "service/submitqueue/gateway/server/Dockerfile");
// values are workspace-relative runfile paths, each of which must be declared
// as a `data` dependency of the test target. This keeps image builds hermetic:
// docker only ever sees files Bazel knows about, never the source checkout.
func WithBuildContext(files map[string]string) ComposeOption {
	return func(o *composeOptions) {
		o.buildContextFiles = files
	}
}

// WithOverlay merges additional compose files over the base one, in the order
// given, exactly as `docker compose -f base.yml -f overlay.yml` does.
//
// It exists so a variant stack can state only what differs from the base —
// a couple of environment variables and volumes — instead of copying the whole
// service definition. A copy is the thing that rots: services added to the base
// file never reach the duplicate, and nothing fails until the variant is run.
//
// Each overlay must be declared as a `data` dependency of the test target, and
// each participates in the input hash alongside the base file.
func WithOverlay(paths ...string) ComposeOption {
	return func(o *composeOptions) {
		o.overlays = append(o.overlays, paths...)
	}
}

// NewComposeStack creates a new compose stack from the given docker-compose file.
// Automatically registers cleanup to tear down the stack.
// testContext should describe what's being tested (e.g., "gateway", "storage", "e2e-submitqueue").
func NewComposeStack(t *testing.T, log *TestLogger, ctx context.Context, composeFile, testContext string, opts ...ComposeOption) *ComposeStack {
	t.Helper()

	var options composeOptions
	for _, opt := range opts {
		opt(&options)
	}

	// Setup Docker environment
	setupDockerEnv(t)
	composeExecutable, err := runfiles.Rlocation("rules_docker_compose/docker_compose/current_docker_compose_toolchain/docker-compose")
	require.NoError(t, err)

	// The image prefix is derived from the content of the declared inputs, so
	// every compose file participates in the hash alongside the staged build
	// context files.
	inputHash := sha256.New()
	composeFiles := make([]string, 0, 1+len(options.overlays))
	for _, file := range append([]string{composeFile}, options.overlays...) {
		absPath, err := filepath.Abs(file)
		require.NoError(t, err, "failed to get absolute path to compose file %s", file)
		hashFile(t, inputHash, file, absPath)
		composeFiles = append(composeFiles, absPath)
	}

	buildContextDir := ""
	if len(options.buildContextFiles) > 0 {
		buildContextDir = stageBuildContext(t, inputHash, options.buildContextFiles)
	}

	// Generate meaningful project name: sq-test-{context}-{short-timestamp}
	// Results in container names like: sq-test-gateway-a1b2c3d-mysql-app-1
	timestamp := fmt.Sprintf("%x", time.Now().UnixNano()&0xFFFFFF) // Last 6 hex digits
	projectName := fmt.Sprintf("sq-test-%s-%s", testContext, timestamp)

	stack := &ComposeStack{
		composeFiles: composeFiles,
		projectName:  projectName,
		t:            t,
		log:          log,
		ctx:          ctx,
		composeCmd:   []string{composeExecutable},
		composeEnv:   composeEnvironment(inputHash.Sum(nil), buildContextDir),
	}

	// Register cleanup
	t.Cleanup(func() {
		stack.stopLogs()

		if os.Getenv("SKIP_CLEANUP") == "true" {
			log.Logf("SKIP_CLEANUP=true - keeping containers for inspection")
			log.Logf("Container prefix: %s", projectName)
			composeCmd := strings.Join(stack.composeCmd, " ")
			log.Logf("Clean up manually: %s %s -p %s down -v",
				composeCmd, strings.Join(stack.fileArgs(), " "), projectName)
			return
		}

		log.Logf("Tearing down compose stack")
		stack.down()
	})

	return stack
}

// Up starts the named services, or all services when none are supplied.
// Uses --wait to block until all services with healthcheck directives are healthy.
func (s *ComposeStack) Up(services ...string) error {
	s.t.Helper()
	s.log.Logf("Starting compose stack from %s", strings.Join(s.composeFiles, " + "))

	args := s.command(append([]string{"up", "-d", "--build", "--wait"}, services...)...)
	cmd := exec.CommandContext(s.ctx, s.composeCmd[0], args...)
	cmd.Env = s.composeEnv
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	if err := cmd.Run(); err != nil {
		return fmt.Errorf("failed to start compose stack: %w", err)
	}

	s.log.Logf("Compose stack started successfully")
	s.stopLogs()
	s.tailLogs()
	return nil
}

// down stops and removes all services and volumes in the compose stack.
// Locally built images are named after the hash of their declared inputs and
// remain cached for subsequent runs with the same build context.
func (s *ComposeStack) down() {
	s.log.Logf("Stopping compose stack")

	args := s.command("down", "-v")
	cmd := exec.CommandContext(s.ctx, s.composeCmd[0], args...)
	cmd.Env = s.composeEnv
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	if err := cmd.Run(); err != nil {
		s.log.Logf("Warning: failed to stop compose stack: %v", err)
	}
}

// tailLogs starts a background "docker compose logs -f" process that streams
// container logs to stderr in real time. Using os.Stderr instead of t.Log()
// because t.Log() buffers output until the test finishes.
func (s *ComposeStack) tailLogs() {
	args := s.command("logs", "-f")
	cmd := exec.Command(s.composeCmd[0], args...)
	cmd.Env = s.composeEnv
	cmd.Stdout = os.Stderr
	cmd.Stderr = os.Stderr

	if err := cmd.Start(); err != nil {
		s.log.Logf("Warning: failed to tail logs: %v", err)
		return
	}
	s.logCmd = cmd
}

// stopLogs kills the background log-tailing process if running.
func (s *ComposeStack) stopLogs() {
	if s.logCmd != nil && s.logCmd.Process != nil {
		s.logCmd.Process.Kill()
		s.logCmd.Wait()
	}
}

// ServicePort returns the mapped host port for a service's container port.
func (s *ComposeStack) ServicePort(serviceName string, containerPort int) (int, error) {
	s.t.Helper()

	args := s.command("port", serviceName, fmt.Sprintf("%d", containerPort))
	cmd := exec.CommandContext(s.ctx, s.composeCmd[0], args...)
	cmd.Env = s.composeEnv

	output, err := cmd.Output()
	if err != nil {
		return 0, fmt.Errorf("failed to get port for service %s: %w", serviceName, err)
	}

	// Parse output like "0.0.0.0:49153\n"
	// Strip whitespace and split on colon
	outputStr := strings.TrimSpace(string(output))

	// Find the last colon (port separator)
	colonIdx := strings.LastIndex(outputStr, ":")
	if colonIdx < 0 {
		return 0, fmt.Errorf("failed to parse port output: no colon found in %q", outputStr)
	}

	portStr := outputStr[colonIdx+1:]
	var port int
	_, err = fmt.Sscanf(portStr, "%d", &port)
	if err != nil {
		return 0, fmt.Errorf("failed to parse port number from %q: %w", portStr, err)
	}

	return port, nil
}

// ServiceHost returns the host:port address for a service.
func (s *ComposeStack) ServiceHost(serviceName string, containerPort int) (string, error) {
	s.t.Helper()

	port, err := s.ServicePort(serviceName, containerPort)
	if err != nil {
		return "", err
	}

	return fmt.Sprintf("localhost:%d", port), nil
}

// ConnectMySQLService connects to a MySQL service by name in the compose stack.
// Requires that Up() has been called first — the TCP-based healthcheck in
// docker-compose ensures MySQL is accepting TCP connections before Up() returns.
func (s *ComposeStack) ConnectMySQLService(serviceName string) (*sql.DB, error) {
	s.t.Helper()

	dsn, err := s.MySQLServiceDSN(serviceName)
	if err != nil {
		return nil, err
	}

	db, err := sql.Open("mysql", dsn)
	if err != nil {
		return nil, fmt.Errorf("failed to open mysql connection: %w", err)
	}

	if err = db.Ping(); err != nil {
		db.Close()
		return nil, fmt.Errorf("failed to ping %s mysql: %w", serviceName, err)
	}

	port, _ := s.ServicePort(serviceName, 3306) // We already got the port successfully
	s.log.Logf("Connected to %s MySQL at localhost:%d", serviceName, port)

	// Register cleanup
	s.t.Cleanup(func() {
		s.log.Logf("Closing %s MySQL connection", serviceName)
		db.Close()
	})

	return db, nil
}

// MySQLServiceDSN returns the DSN string for a MySQL service.
// Useful when the implementation manages its own database connection.
func (s *ComposeStack) MySQLServiceDSN(serviceName string) (string, error) {
	s.t.Helper()

	port, err := s.ServicePort(serviceName, 3306)
	if err != nil {
		return "", err
	}

	return fmt.Sprintf("root:root@tcp(localhost:%d)/submitqueue?parseTime=true", port), nil
}

// ConnectGRPC creates a gRPC client connection to a service.
func (s *ComposeStack) ConnectGRPC(serviceName string, containerPort int) (*grpc.ClientConn, error) {
	s.t.Helper()

	addr, err := s.ServiceHost(serviceName, containerPort)
	if err != nil {
		return nil, err
	}

	// Retry connection a few times as service might still be starting
	var conn *grpc.ClientConn
	for i := 0; i < 10; i++ {
		conn, err = grpc.NewClient(addr, grpc.WithTransportCredentials(insecure.NewCredentials()))
		if err == nil {
			break
		}
		time.Sleep(1 * time.Second)
	}

	if err != nil {
		return nil, fmt.Errorf("failed to connect to %s after retries: %w", serviceName, err)
	}

	s.log.Logf("Connected to %s at %s", serviceName, addr)

	// Register cleanup
	s.t.Cleanup(func() {
		s.log.Logf("Closing gRPC connection to %s", serviceName)
		conn.Close()
	})

	return conn, nil
}

// StopService sends SIGTERM to a service and waits for it to stop.
// timeoutSec is the maximum time to wait before Docker sends SIGKILL.
func (s *ComposeStack) StopService(serviceName string, timeoutSec int) error {
	s.t.Helper()

	s.log.Logf("Stopping service %s (timeout %ds)", serviceName, timeoutSec)

	args := s.command(
		"stop", "-t", fmt.Sprintf("%d", timeoutSec), serviceName)
	cmd := exec.CommandContext(s.ctx, s.composeCmd[0], args...)
	cmd.Env = s.composeEnv
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	if err := cmd.Run(); err != nil {
		return fmt.Errorf("failed to stop service %s: %w", serviceName, err)
	}

	s.log.Logf("Service %s stopped", serviceName)
	return nil
}

// ServiceExitCode returns the exit code of a stopped service container.
// Must be called after the service has exited.
func (s *ComposeStack) ServiceExitCode(serviceName string) (int, error) {
	s.t.Helper()

	// Get container ID for the service
	args := s.command(
		"ps", "-a", "-q", serviceName)
	cmd := exec.CommandContext(s.ctx, s.composeCmd[0], args...)
	cmd.Env = s.composeEnv
	output, err := cmd.Output()
	if err != nil {
		return 0, fmt.Errorf("failed to get container ID for service %s: %w", serviceName, err)
	}

	containerID := strings.TrimSpace(string(output))
	if containerID == "" {
		return 0, fmt.Errorf("no container found for service %s", serviceName)
	}

	// Get exit code via docker inspect
	inspectCmd := exec.CommandContext(s.ctx, "docker", "inspect",
		"--format", "{{.State.ExitCode}}", containerID)
	inspectOutput, err := inspectCmd.Output()
	if err != nil {
		return 0, fmt.Errorf("failed to inspect container %s: %w", containerID, err)
	}

	var exitCode int
	_, err = fmt.Sscanf(strings.TrimSpace(string(inspectOutput)), "%d", &exitCode)
	if err != nil {
		return 0, fmt.Errorf("failed to parse exit code from %q: %w", string(inspectOutput), err)
	}

	s.log.Logf("Service %s exit code: %d", serviceName, exitCode)
	return exitCode, nil
}

// setupDockerEnv configures the Docker CLI environment for compose commands.
func setupDockerEnv(t *testing.T) {
	t.Helper()

	// Ensure HOME is set for Docker config
	if os.Getenv("HOME") == "" {
		t.Setenv("HOME", t.TempDir())
	}

	// Bazel's scratch HOME hides Docker contexts and credentials. Preserve
	// the invoking user's Docker config unless one was supplied explicitly.
	if os.Getenv("DOCKER_CONFIG") == "" {
		if u, err := user.Current(); err == nil && u.HomeDir != "" {
			dockerConfig := filepath.Join(u.HomeDir, ".docker")
			if _, statErr := os.Stat(dockerConfig); statErr == nil {
				t.Setenv("DOCKER_CONFIG", dockerConfig)
			}
		}
	}
}

// stageBuildContext copies the given runfiles into a temporary directory that
// serves as the docker build context, feeding each destination path and file
// content into inputHash in deterministic (sorted) order. Runfiles are
// symlinks into Bazel's output tree, and docker's context upload does not
// follow symlinks, so the content is copied. Each staged file keeps its source
// mode, so service binaries stay executable; docker preserves the mode on COPY.
func stageBuildContext(t *testing.T, inputHash hash.Hash, files map[string]string) string {
	t.Helper()

	dests := make([]string, 0, len(files))
	for dest := range files {
		dests = append(dests, dest)
	}
	sort.Strings(dests)

	dir := t.TempDir()
	for _, dest := range dests {
		src := files[dest]
		srcFile, err := os.Open(Runfile(src))
		require.NoError(t, err, "failed to open build context input %s (is it declared as a data dependency?)", src)

		info, err := srcFile.Stat()
		require.NoError(t, err, "failed to stat build context input %s", src)

		destPath := filepath.Join(dir, dest)
		require.NoError(t, os.MkdirAll(filepath.Dir(destPath), 0o755), "failed to create build context dir for %s", dest)

		destFile, err := os.OpenFile(destPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, info.Mode().Perm())
		require.NoError(t, err, "failed to create build context file %s", dest)

		_, _ = io.WriteString(inputHash, dest)
		_, _ = inputHash.Write([]byte{0})
		_, err = io.Copy(io.MultiWriter(destFile, inputHash), srcFile)
		require.NoError(t, err, "failed to stage build context file %s", dest)
		require.NoError(t, destFile.Close(), "failed to close build context file %s", dest)
		require.NoError(t, srcFile.Close(), "failed to close build context input %s", src)
	}
	return dir
}

// hashFile feeds a logical path marker and the content of the file at path
// into inputHash.
func hashFile(t *testing.T, inputHash hash.Hash, logicalPath, path string) {
	t.Helper()

	_, _ = io.WriteString(inputHash, logicalPath)
	_, _ = inputHash.Write([]byte{0})

	f, err := os.Open(path)
	require.NoError(t, err, "failed to open declared input %s", logicalPath)
	_, err = io.Copy(inputHash, f)
	require.NoError(t, err, "failed to hash declared input %s", logicalPath)
	require.NoError(t, f.Close(), "failed to close declared input %s", logicalPath)
}

// composeEnvironment returns the environment used by every compose command.
// The image prefix is derived from the content of the declared inputs (compose
// file plus staged build context), so runs with identical inputs reuse the
// docker build cache while different revisions — including concurrent runs
// from separate worktrees against one daemon — never collide on an image tag.
func composeEnvironment(inputHash []byte, buildContextDir string) []string {
	imagePrefix := fmt.Sprintf("sq-test-%x", inputHash[:6])

	env := os.Environ()
	env = append(env, "SQ_DOCKER_IMAGE_PREFIX="+imagePrefix)
	env = append(env, "SQ_MYSQL_DATA_MOUNT_TYPE=tmpfs")
	env = append(env, "SQ_MYSQL_INITDB_SKIP_TZINFO=1")
	if buildContextDir != "" {
		// The compose files resolve their build context from REPO_ROOT; in
		// tests it points at the staged minimal context, not the checkout.
		env = append(env, "REPO_ROOT="+buildContextDir)
	}
	return env
}

import fcntl
import subprocess
import tempfile
from pathlib import Path

from python.runfiles import runfiles


def compose_command() -> list[str]:
    executable = runfiles.Create().Rlocation(
        "rules_docker_compose/docker_compose/current_docker_compose_toolchain/docker-compose"
    )
    if executable is None:
        raise RuntimeError("The pinned Compose executable is missing from Bazel runfiles")
    return [executable]


def load_project_images(
    loaders: list[Path], tags: dict[str, str], *, env: dict[str, str]
) -> None:
    # Shared loader tags are locked until each stack has its own image tags.
    with (Path(tempfile.gettempdir()) / "submitqueue-web-e2e-image.lock").open(
        "w", encoding="utf-8"
    ) as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        for loader in loaders:
            subprocess.run([str(loader)], env=env, check=True)
        for source, destination in tags.items():
            subprocess.run(["docker", "tag", source, destination], env=env, check=True)


def apply_schemas(groups: list[tuple[Path, str]], *, env: dict[str, str]) -> None:
    for folder, container in groups:
        for schema in sorted(folder.glob("*.sql")):
            with schema.open(encoding="utf-8") as statements:
                subprocess.run(
                    [
                        "docker",
                        "exec",
                        "-i",
                        container,
                        "mysql",
                        "-uroot",
                        "-proot",
                        "submitqueue",
                    ],
                    env=env,
                    stdin=statements,
                    check=True,
                    text=True,
                )


def published_port(container: str, port: str, *, env: dict[str, str]) -> str:
    address = subprocess.check_output(
        ["docker", "port", container, port], env=env, text=True
    )
    return address.splitlines()[0].rsplit(":", 1)[-1]

